// Simple test to verify image tool path resolution fix
import path from "node:path";

// URL detection helpers
const isHttpUrl = (s) => /^https?:\/\//i.test(s);
const isDataUrl = (s) => /^data:/i.test(s);

// Simulate: resolveImagePath(path, workspaceDir, sandboxConfig, isHttpUrl, isDataUrl)
function resolveImagePath(imageRaw, workspaceDir, sandboxConfig) {
  if (sandboxConfig) {
    return imageRaw;
  }
  if (imageRaw.startsWith("~")) {
    // Simulate resolveUserPath
    return path.resolve("/home/user", imageRaw.slice(1));
  }
  // For relative paths, resolve against workspaceDir instead of process.cwd()
  // Skip this for URLs (http/https/data) which should be handled as-is
  if (workspaceDir && !isHttpUrl(imageRaw) && !isDataUrl(imageRaw) && !path.isAbsolute(imageRaw)) {
    return path.resolve(workspaceDir, imageRaw);
  }
  return imageRaw;
}

// Test cases
const tests = [
  {
    name: "Absolute path",
    input: "/absolute/path/to/image.png",
