 import { buildProviderRegistry } from "../../media-understanding/runner.js";
 import { loadWebMedia } from "../../media/web-media.js";
@@ -387,6 +388,12 @@ export function createImageTool(options?: {
           if (imageRaw.startsWith("~")) {
             return resolveUserPath(imageRaw);
           }
+          // For relative paths, resolve against workspaceDir instead of process.cwd()
+          // Skip this for URLs (http/https/data) which should be handled as-is
+          const workspaceDir = options?.workspaceDir?.trim();
+          if (workspaceDir && !isHttpUrl && !isDataUrl && !path.isAbsolute(imageRaw)) {
+            return path.resolve(workspaceDir, imageRaw);
+          }
           return imageRaw;
         })();
         const resolvedPathInfo: { resolved: string; rewrittenFrom?: string } = isDataUrl
```

### 测试结果

